          ) : (
            <button onClick={finish} disabled={dl.busy}
              className="btn-gold flex-1 px-5 py-3 disabled:opacity-40"><Check className="w-5 h-5" /> {dl.finished ? "ابدأ" : "ابدأ (بلا تحميل)"}</button>
          )}
        </div>
      </div>
    </div>
  );
}

