  // توحيد بالموقع: يُسنِد كل مربّع آية إلى السورة التي يقع مركزه داخل منطقتها (بلا نقل يدوي)
  const unifyBySurahLocation = () => {
    const withSurah = regions.filter(r => r.surah);
