                <button onClick={() => moveInOrder(pos, 1)} disabled={pos === draftSrcOrder.length - 1} className="p-1.5 rounded-md bg-muted text-foreground disabled:opacity-30 active:scale-95"><ChevronDown className="h-4 w-4" /></button>
