          }
        }} onCancel={() => { setPinFlow(null); setPendingMode(null); }} />
      )}

      {showSupport && <SupportModal onClose={() => setShowSupport(false)} />}
    </div>
  );
}

self.addEventListener('install', function (event) {
  // @ts-ignore
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', function (event) {
  // @ts-ignore
  event.waitUntil(self.clients.claim());
});

self.addEventListener('push', function (event) {
  let data = {};
  try { data = event.data?.json() || {}; } catch (e) {}
  const title = data.title || 'Learn Quran Kids';
  const options = {
    body: data.body || '',
    icon: data.icon || '/assets/icons/icon-192.png',
    data: data.url || '/'
  };
  // @ts-ignore
  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', function (event) {
  event.notification.close();
  const url = event.notification.data || '/';
  // @ts-ignore
  event.waitUntil(self.clients.openWindow(url));
});

type WorkboxManifestEntry = { url: string; revision?: string };
// @ts-ignore
const precacheManifest: WorkboxManifestEntry[] = self.__WB_MANIFEST || [];
void precacheManifest;

import { useEffect, useRef } from "react";
import { supabase } from "@/lib/supabase";
import { getDeviceId } from "./deviceInfo";
import { getKidsSchedule, isTimeAllowed } from "../data/kidsSchedule";
import { toast } from "@/hooks/use-toast";

let notificationPermissionRequested = false;

// Request notification permission
export async function requestNotificationPermission() {
  if (typeof window === "undefined" || !("Notification" in window)) return false;
  if (Notification.permission === "granted") return true;
  if (Notification.permission !== "denied") {
    notificationPermissionRequested = true;
    const permission = await Notification.requestPermission();
    return permission === "granted";
  }
  return false;
}

export function showLocalNotification(title: string, body: string) {
  if (typeof window !== "undefined" && "Notification" in window && Notification.permission === "granted") {
    try {
      new Notification(title, { body, icon: "/icon.png", tag: title, renotify: true });
      return;
    } catch (err) {
      console.error("Notification display failed", err);
    }
  }

  // Fallback to toast when native notifications are not available.
  toast({ title, description: body });
}

export function useBackgroundNotifications() {
  const initialized = useRef(false);

  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;

    // Ask for permission silently when the app starts.
    void requestNotificationPermission().then((granted) => {
      // Push notifications not yet fully implemented
    });

    const deviceId = getDeviceId();

    // 1. Listen for new announcements
    const announceSub = supabase
      .channel("public:announcements")
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "announcements" },
        (payload) => {
          const newAnnounce = payload.new;
          if (newAnnounce.is_active) {
            showLocalNotification("إعلان جديد 📢", newAnnounce.title || "تفقّد الإشعارات لمعرفة الجديد!");
          }
        }
      )
      .subscribe();

    // 2. Listen for support replies
    let supportSub: any = null;
    async function listenSupport() {
      try {
        const { data: conv } = await supabase
          .from("support_conversations")
          .select("id")
          .eq("device_id", deviceId)
          .maybeSingle();

        if (conv) {
          supportSub = supabase
            .channel(`public:support_messages:${conv.id}`)
            .on(
              "postgres_changes",
              { event: "INSERT", schema: "public", table: "support_messages", filter: `conversation_id=eq.${conv.id}` },
              (payload) => {
                const msg = payload.new;
                // Only notify if sender is admin or bot
                if (msg.sender !== "user") {
                  showLocalNotification("رد من الدعم الفني 💬", msg.body || "لديك رسالة جديدة في الدعم الفني");
                }
              }
            )
            .subscribe();
        }
      } catch (err) {
        console.error("Support listener err", err);
      }
    }
    listenSupport();

    // 3. Kids Schedule Reminder / Enforcer
    const timer = setInterval(() => {
       const schedule = getKidsSchedule();
       if (!schedule.enabled) return;

       // If currently in kids mode, check if time is up
       const isKids = window.location.pathname === "/games";
       const allowed = isTimeAllowed();

       if (isKids && !allowed) {
         const message = "لقد انتهى الوقت المخصص لك اليوم. نراك لاحقاً!";
         showLocalNotification("انتهى وقت اللعب ⏰", message);
         // Optionally, we could force them out, but we handle that in KidsGames directly.
       }
    }, 60000); // Check every minute

    return () => {
      supabase.removeChannel(announceSub);
      if (supportSub) supabase.removeChannel(supportSub);
      clearInterval(timer);
    };
  }, []);
}

/**
 * Virtual scrolling utility for large lists
 * Renders only visible items to improve performance
 */

import React from 'react';

export interface VirtualScrollOptions {
  itemHeight: number;
  containerHeight: number;
  buffer?: number; // extra items to render above/below visible area
}

export interface VirtualScrollResult {
  startIndex: number;
  endIndex: number;
  offsetY: number;
}

/**
 * Calculate which items should be visible
 */
export function calculateVisibleRange(
  scrollOffset: number,
  itemCount: number,
  options: VirtualScrollOptions
): VirtualScrollResult {
  const { itemHeight, containerHeight, buffer = 5 } = options;
  
  const visibleCount = Math.ceil(containerHeight / itemHeight);
  const startIndex = Math.max(0, Math.floor(scrollOffset / itemHeight) - buffer);
  const endIndex = Math.min(itemCount, startIndex + visibleCount + buffer * 2);
  const offsetY = startIndex * itemHeight;

  return { startIndex, endIndex, offsetY };
}

/**
 * Hook for virtual scrolling (simplified for manual implementation)
 */
export function useVirtualScroll(
  itemCount: number,
  options: VirtualScrollOptions
) {
  const [scrollOffset, setScrollOffset] = React.useState(0);
  const visible = calculateVisibleRange(scrollOffset, itemCount, options);
  
  return {
    ...visible,
    onScroll: (e: React.UIEvent<HTMLDivElement>) => {
      setScrollOffset((e.target as HTMLDivElement).scrollTop);
    },
    totalHeight: itemCount * options.itemHeight,
  };
}

/**
 * For use with React.lazy for dynamic imports
 */
export const createLazyComponent = (importFn: () => Promise<any>) => {
  return React.lazy(importFn);
};
